<template>
<main class="studio">
  <aside><button class="brand" @click="router.push('/dashboard')"><i>D</i><span>DokiAI<small>文字创作中心 V2</small></span></button><div class="project-mini"><small>当前项目</small><b>{{ settings.title||'未命名论文项目' }}</b><span>{{ project.current_stage||'等待配置' }}</span></div><nav><button v-for="n in nav" :key="n.key" :class="{active:active===n.key}" @click="active=n.key"><i>{{ n.no }}</i><span>{{ n.label }}<small>{{ n.desc }}</small></span></button></nav><button class="literature" @click="router.push('/literature')">⌕ 文献中心</button></aside>
  <section class="main"><header><div><span>AI PAPER PRODUCTION</span><h1>{{ currentNav.label }}</h1><p>{{ currentNav.long }}</p></div><button @click="router.push('/dashboard')">返回工作台 ↗</button></header>

    <section v-if="active==='settings'" class="panel settings">
      <div class="section-title"><span>01 / PROJECT FOUNDATION</span><h2>项目基础信息</h2><p>这些信息会成为全局变量，被绪论、案例分析、调研和图片说明共同调用。</p></div>
      <div class="form-grid"><label class="wide">论文题目<input v-model="settings.title" placeholder="请输入完整论文题目"></label><label>写作类型<select v-model="settings.writingType"><option>毕业论文</option><option>设计说明书</option><option>项目报告</option></select></label><label>专业方向<input v-model="settings.major" placeholder="例如：工商管理"></label><label>语言风格<select v-model="settings.writingTone"><option>本科论文</option><option>学术正式</option><option>简洁严谨</option></select></label><label>目标字数<input v-model.number="settings.targetWordCount" type="number" min="1000"></label></div>
      <h3 class="subhead">论文类型 <small>不同类型将影响大纲与生成策略</small></h3><div class="paper-types"><button v-for="t in paperTypes" :key="t.value" :class="{selected:settings.paperType===t.value}" @click="settings.paperType=t.value"><i>{{ t.icon }}</i><b>{{ t.label }}</b><small>{{ t.desc }}</small></button></div>
      <h3 class="subhead">研究场景定位 <small>用于建立论文的真实语境</small></h3><div class="form-grid scene"><label>研究对象<input v-model="settings.researchObject" placeholder="请输入研究对象"></label><label>企业 / 机构<input v-model="settings.researchOrganization" placeholder="请输入企业或机构"></label><label>地区<input v-model="settings.researchLocation" placeholder="例如：福建厦门"></label><label>行业领域<input v-model="settings.researchIndustry" placeholder="例如：酒店旅游"></label><label class="wide">应用场景<textarea v-model="settings.researchScene" rows="3" placeholder="例如：在线评价影响游客消费决策"></textarea></label><label class="wide">特殊要求<textarea v-model="settings.requirements" rows="3" placeholder="学校格式、必须覆盖的内容、写作限制等"></textarea></label></div><div class="actionbar"><span>信息将自动保存到后续模块</span><button class="primary" :disabled="busy" @click="saveProject">{{ projectId?'保存并进入大纲设计':'创建项目并继续' }} →</button></div>
    </section>

    <section v-if="active==='outline'" class="panel outline-panel">
      <div class="outline-top"><div class="section-title"><span>02 / OUTLINE & RESOURCES</span><h2>章节生产蓝图</h2><p>先规划章节，再为每章选择正文、图片、表格和可编辑图表。</p></div><div class="outline-actions"><select v-model="outline.template"><option v-for="t in templates" :key="t.key" :value="t.key">{{ t.name }}</option></select><label><input v-model="outline.aiOptimize" type="checkbox"> AI 优化标题</label><button class="primary" :disabled="!projectId||busy" @click="designOutline">生成大纲</button></div></div>
      <div v-if="!chapters.length" class="empty">创建项目并生成大纲后，可在这里配置每个章节。</div>
      <div v-else class="outline-workspace"><div class="chapter-list"><small>CHAPTERS</small><button v-for="c in chapters" :key="c.id" :class="{active:selectedChapter?.id===c.id}" @click="selectChapter(c)"><i>{{ String(c.chapter_no).padStart(2,'0') }}</i><span><b>第{{ c.chapter_no }}章</b><small>{{ c.title }}</small></span><em>›</em></button></div>
        <div v-if="selectedChapter" class="chapter-config"><div class="chapter-head"><div><span>CHAPTER {{ selectedChapter.chapter_no }}</span><h2>第{{ selectedChapter.chapter_no }}章 {{ selectedChapter.title }}</h2><p>{{ selectedChapter.sections?.map(s=>s.title).join(' · ') }}</p></div><b>{{ enabledCount }} 项资源</b></div><h3>需要生成</h3><div class="resource-grid"><button v-for="r in resourceOptions" :key="r.type" :class="{enabled:resourceForm[r.type].enabled,locked:r.type==='IMAGE_SEARCH'&&selectedChapter.chapter_no>2}" @click="toggleResource(r)"><i>{{ r.icon }}</i><span><b>{{ r.label }}</b><small>{{ resourceHint(r) }}</small></span><em>{{ resourceForm[r.type].enabled?'✓':'＋' }}</em></button></div>
          <div class="quantity-grid"><label v-if="resourceForm.IMAGE_SEARCH.enabled&&selectedChapter.chapter_no<=2">联网图片数量<div><button @click="adjustResource('IMAGE_SEARCH',-1)">−</button><b>{{ resourceForm.IMAGE_SEARCH.quantity }}</b><button @click="adjustResource('IMAGE_SEARCH',1)">＋</button></div><small>仅第一、二章允许自动搜索</small></label><label v-if="resourceForm.IMAGE_UPLOAD.enabled">用户图片<div class="upload-inline"><el-upload v-model:file-list="imageFiles" multiple :auto-upload="false" accept=".png,.jpg,.jpeg"><button>选择图片</button></el-upload><button :disabled="!imageFiles.length||busy" @click="uploadImages">上传并分析</button></div><small>上传后作为本章图片说明上下文</small></label><label v-if="resourceForm.TABLE.enabled">原生表格数量<div><button @click="adjustResource('TABLE',-1)">−</button><b>{{ resourceForm.TABLE.quantity }}</b><button @click="adjustResource('TABLE',1)">＋</button></div><small>以 Word 原生表格输出</small></label><label v-if="resourceForm.CHART.enabled">可编辑图表数量<div><button @click="adjustResource('CHART',-1)">−</button><b>{{ resourceForm.CHART.quantity }}</b><button @click="adjustResource('CHART',1)">＋</button></div><small>SVG / Word 兼容</small></label></div><div class="chapter-save"><span>图片联网规则已按章节自动限制</span><button class="primary" :disabled="busy" @click="saveResources">保存本章配置</button></div>
        </div></div>
    </section>

    <section v-if="active==='content'" class="panel"><div class="section-title"><span>03 / AI GENERATION</span><h2>结构化正文生成</h2><p>系统将依次读取项目设置、研究场景、章节结构、资源配置、图片和参考文献。</p></div><div class="pipeline"><span v-for="x in ['项目设置','研究场景','章节结构','资源配置','图片/表格/图表','生成正文']" :key="x">{{ x }}</span></div><label class="references">参考文献<textarea v-model="referencesText" rows="8" placeholder="从文献中心粘贴 GB/T 7714 引用"></textarea></label><div class="actionbar"><button class="secondary" @click="saveReferencesOnly">保存参考文献</button><button class="primary" :disabled="!projectId||busy" @click="generateContent">{{ busy?'正在组织论文内容…':'开始生成正文' }}</button></div><div v-if="project.preview_text" class="preview"><header><b>正文预览</b><button @click="copyPreview">复制</button></header><pre>{{ project.preview_text }}</pre></div></section>
    <section v-if="active==='document'" class="panel"><div class="section-title"><span>04 / WORD PROCESSING</span><h2>Word 文档处理</h2><p>将正文、原生表格、可编辑图表、图片题注与参考文献整理为正式文档。</p></div><div class="doc-process"><article v-for="x in [['A','自动目录'],['T','原生表格'],['◫','图表与题注'],['¶','页眉页脚'],['文','参考文献']]" :key="x[1]"><i>{{ x[0] }}</i><b>{{ x[1] }}</b><span>自动检查与排版</span></article></div><button class="primary export-btn" :disabled="!projectId||busy||!project.preview_text" @click="exportDocx">处理并生成 DOCX →</button></section>
    <section v-if="active==='export'" class="panel"><div class="section-title"><span>05 / DELIVERY</span><h2>导出成果</h2><p>下载正式论文文档，生成记录会持续保留在项目中。</p></div><div v-if="files.length" class="files"><article v-for="f in files" :key="f.id"><i>DOCX</i><div><b>{{ f.file_name }}</b><span>可编辑 Word 文档</span></div><button @click="download(f)">下载文件 ↓</button></article></div><div v-else class="empty">完成文档处理后，导出成果将显示在这里。</div></section>
  </section>
</main>
</template>
<script setup>
import{computed,onMounted,ref}from'vue';import{ElMessage}from'element-plus';import{useRouter}from'vue-router';import{createWritingV2Project,designWritingV2Outline,downloadArtifact,exportWritingV2Docx,generateWritingV2Content,getWritingV2Project,getWritingV2Templates,saveWritingV2ChapterResources,saveWritingV2References,saveWritingV2Settings,uploadWritingV2Images}from'../../api/rewrite'
const router=useRouter(),active=ref('settings'),busy=ref(false),projectId=ref(sessionStorage.getItem('dropai_writing_v2_project_id')||''),project=ref({}),templates=ref([]),selectedChapter=ref(null),imageFiles=ref([]),referencesText=ref(sessionStorage.getItem('dropai_literature_citations')||'')
const settings=ref({title:'',major:'',writingType:'毕业论文',targetWordCount:8000,writingTone:'本科论文',requirements:'',paperType:'THEORETICAL',researchObject:'',researchOrganization:'',researchLocation:'',researchIndustry:'',researchScene:''}),outline=ref({template:'business',aiOptimize:true})
const nav=[{key:'settings',no:'01',label:'项目设置',desc:'定位研究场景',long:'定义论文类型与全局研究语境。'},{key:'outline',no:'02',label:'大纲设计',desc:'规划章节资源',long:'为每个章节建立清晰的内容生产蓝图。'},{key:'content',no:'03',label:'正文生成',desc:'结构化 AI 写作',long:'基于已经确认的结构与资源生成正文。'},{key:'document',no:'04',label:'文档处理',desc:'Word 自动排版',long:'整理目录、图表、题注与参考文献。'},{key:'export',no:'05',label:'导出成果',desc:'交付正式文档',long:'下载并管理最终论文成果。'}],paperTypes=[{value:'THEORETICAL',label:'理论研究',icon:'∑',desc:'理论框架与文献论证'},{value:'CASE_ANALYSIS',label:'案例分析',icon:'◎',desc:'企业、地区与用户对象'},{value:'ENTERPRISE_PRACTICE',label:'企业实践',icon:'▥',desc:'业务问题与实践路径'},{value:'PRODUCT_DESIGN',label:'产品设计',icon:'◇',desc:'用户需求与方案实现'},{value:'SOFTWARE_SYSTEM',label:'软件系统设计',icon:'⌘',desc:'需求、架构、数据库与流程'},{value:'ENGINEERING_DESIGN',label:'工程设计',icon:'△',desc:'参数、结构与验证分析'}]
const resourceOptions=[{type:'TEXT',label:'正文',icon:'文'},{type:'IMAGE_SEARCH',label:'联网图片',icon:'⌕'},{type:'IMAGE_UPLOAD',label:'上传图片',icon:'↑'},{type:'TABLE',label:'原生表格',icon:'▦'},{type:'CHART',label:'数据图表',icon:'▥'},{type:'FLOW',label:'流程图',icon:'⌁'},{type:'MODEL',label:'模型图',icon:'◇'},{type:'AI_ANALYSIS',label:'AI 图片分析',icon:'✦'}]
const blankResources=()=>Object.fromEntries(resourceOptions.map(r=>[r.type,{enabled:r.type==='TEXT',quantity:r.type==='TEXT'?1:0}]))
const resourceForm=ref(blankResources()),currentNav=computed(()=>nav.find(n=>n.key===active.value)||nav[0]),chapters=computed(()=>project.value.chapters||[]),files=computed(()=>project.value.files||[]),enabledCount=computed(()=>Object.values(resourceForm.value).filter(x=>x.enabled).length)
function hydrate(){Object.assign(settings.value,{title:project.value.title||'',major:project.value.major||'',writingType:project.value.document_type||'毕业论文',targetWordCount:project.value.target_word_count||8000,writingTone:project.value.writing_tone||'本科论文',requirements:project.value.requirements||'',paperType:project.value.paper_type||'THEORETICAL',researchObject:project.value.research_object||'',researchOrganization:project.value.research_organization||'',researchLocation:project.value.research_location||'',researchIndustry:project.value.research_industry||'',researchScene:project.value.research_scene||''})}
function selectChapter(c){selectedChapter.value=c;resourceForm.value=blankResources();(c.resources||[]).forEach(r=>resourceForm.value[r.resource_type]={enabled:Boolean(r.enabled),quantity:Number(r.quantity||0)})}
function toggleResource(r){if(r.type==='TEXT')return;if(r.type==='IMAGE_SEARCH'&&selectedChapter.value.chapter_no>2)return ElMessage.warning('仅第一章、第二章允许联网搜索图片');resourceForm.value[r.type].enabled=!resourceForm.value[r.type].enabled;if(resourceForm.value[r.type].enabled&&!resourceForm.value[r.type].quantity)resourceForm.value[r.type].quantity=1}
function resourceHint(r){if(r.type==='IMAGE_SEARCH'&&selectedChapter.value?.chapter_no>2)return'第三章以后不可用';return resourceForm.value[r.type].enabled?`${resourceForm.value[r.type].quantity} 项已启用`:'点击启用'}function adjustResource(k,d){resourceForm.value[k].quantity=Math.max(1,Math.min(10,resourceForm.value[k].quantity+d))}
async function load(){templates.value=await getWritingV2Templates();if(projectId.value){project.value=await getWritingV2Project(projectId.value);hydrate();if(chapters.value.length)selectChapter(chapters.value[0])}}
async function saveProject(){if(!settings.value.title.trim())return ElMessage.warning('请填写论文题目');busy.value=true;try{project.value=projectId.value?await saveWritingV2Settings(projectId.value,settings.value):await createWritingV2Project({...settings.value,template:outline.value.template});projectId.value=project.value.id;sessionStorage.setItem('dropai_writing_v2_project_id',projectId.value);hydrate();active.value='outline';if(chapters.value.length)selectChapter(chapters.value[0]);ElMessage.success('项目设置已保存')}finally{busy.value=false}}
async function designOutline(){busy.value=true;try{project.value=await designWritingV2Outline(projectId.value,outline.value);selectChapter(chapters.value[0]);ElMessage.success('章节蓝图已生成')}finally{busy.value=false}}async function saveResources(){busy.value=true;try{project.value=await saveWritingV2ChapterResources(projectId.value,selectedChapter.value.id,resourceForm.value);selectChapter(chapters.value.find(c=>c.id===selectedChapter.value.id));ElMessage.success('本章资源配置已保存')}finally{busy.value=false}}
async function uploadImages(){busy.value=true;try{project.value=await uploadWritingV2Images(projectId.value,imageFiles.value);imageFiles.value=[];ElMessage.success('图片已上传并纳入章节上下文')}finally{busy.value=false}}async function saveReferencesOnly(){project.value=await saveWritingV2References(projectId.value,referencesText.value);ElMessage.success('参考文献已保存')}async function generateContent(){busy.value=true;try{if(referencesText.value.trim())project.value=await saveWritingV2References(projectId.value,referencesText.value);project.value=await generateWritingV2Content(projectId.value);active.value='document';ElMessage.success('正文生成完成')}finally{busy.value=false}}async function exportDocx(){busy.value=true;try{project.value=await exportWritingV2Docx(projectId.value);active.value='export';ElMessage.success('DOCX 已生成')}finally{busy.value=false}}async function download(f){const blob=await downloadArtifact(f.download_url),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=f.file_name||'DokiAI.docx';a.click();URL.revokeObjectURL(url)}async function copyPreview(){await navigator.clipboard.writeText(project.value.preview_text||'');ElMessage.success('正文已复制')}onMounted(load)
</script>
<style scoped>
